insert into public.reviews(user_id,restaurant_id,dish_id,rating,service_rating,ambience_rating,content,photo_url,created_at) select p.id,d.restaurant_id,d.id,4.5,4.5,4.5,'Sabe aquele primeiro pedaço que já faz valer a visita? Pão fofinho, queijo derretendo e a carne no ponto. Esse aqui entrou para os favoritos. 🍔',d.image_url,now()-interval '2 hours' from public.profiles p cross join public.dishes d where p.username='sofia.almeida' and d.name='Holy Cheeseburger';
insert into public.reviews(user_id,restaurant_id,dish_id,rating,service_rating,ambience_rating,content,photo_url,created_at) select p.id,d.restaurant_id,d.id,5,5,5,'Uma viagem para a Itália sem sair de São Paulo. O pesto é super fresco e a massa tem a textura perfeita. Já quero voltar!',d.image_url,now()-interval '5 hours' from public.profiles p cross join public.dishes d where p.username='pedro.cozinha' and d.name='Tagliatelle ao pesto';
insert into public.reviews(user_id,restaurant_id,dish_id,rating,service_rating,ambience_rating,content,photo_url,created_at) select p.id,d.restaurant_id,d.id,4.5,4.5,4.5,'Meu novo cantinho para um café sem pressa. Cappuccino cremoso, ambiente gostoso e uma playlist que dá vontade de ficar.',d.image_url,now()-interval '8 hours' from public.profiles p cross join public.dishes d where p.username='marina.sabores' and d.name='Cappuccino da casa';
insert into public.reviews(user_id,restaurant_id,dish_id,rating,service_rating,ambience_rating,content,photo_url,created_at) select p.id,d.restaurant_id,d.id,5,5,5,'Caldo intenso, noodles no ponto e aquele ovo perfeito. Uma tigela que abraça. Nossa escolha para um dia mais frio.',d.image_url,now()-interval '12 hours' from public.profiles p cross join public.dishes d where p.username='tasty.guia' and d.name='Shoyu ramen';
insert into public.reviews(user_id,restaurant_id,dish_id,rating,service_rating,ambience_rating,content,photo_url,created_at) select p.id,d.restaurant_id,d.id,4.5,4.5,4.5,'A sobremesa que merece um espacinho extra. Equilíbrio perfeito entre o cremoso e o azedinho das frutas.',d.image_url,now()-interval '24 hours' from public.profiles p cross join public.dishes d where p.username='sofia.almeida' and d.name='Cheesecake de frutas vermelhas';
insert into public.reviews(user_id,restaurant_id,dish_id,rating,service_rating,ambience_rating,content,photo_url,created_at) select p.id,d.restaurant_id,d.id,4.5,4.5,4.5,'Crocante por fora, macio por dentro. Porção generosa e acompanhamentos que fazem toda a diferença.',d.image_url,now()-interval '28 hours' from public.profiles p cross join public.dishes d where p.username='pedro.cozinha' and d.name='Tonkatsu teishoku';
insert into public.reviews(user_id,restaurant_id,dish_id,rating,service_rating,ambience_rating,content,photo_url,created_at) select p.id,d.restaurant_id,d.id,5,5,5,'Café com aroma de fruta e final doce. A equipe explicou a origem e o preparo. Uma experiência completa.',d.image_url,now()-interval '30 hours' from public.profiles p cross join public.dishes d where p.username='marina.sabores' and d.name='Café coado especial';
insert into public.reviews(user_id,restaurant_id,dish_id,rating,service_rating,ambience_rating,content,photo_url,created_at) select p.id,d.restaurant_id,d.id,5,5,5,'Borda leve, molho de tomate com sabor de verdade e muito manjericão. O clássico sempre surpreende.',d.image_url,now()-interval '36 hours' from public.profiles p cross join public.dishes d where p.username='tasty.guia' and d.name='Pizza margherita';
